function runningTotals(nums: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    let s = 0;
    for (let j = 0; j <= i; j++) s += nums[j];
    out.push(s);
  }
  return out;
}

